# Biblioteca de efectos del canal, con criterio de realismo.
# Genera 3d/audio/biblioteca.json: cada sonido con su indicación para ElevenLabs Sound Effects v3,
# su duración, si es bucle, los episodios y efectos de la guía que cubre, y su costo estimado.
# Uso: python3 3d/audio/biblioteca.py
#
# Reglas de las indicaciones:
#   1. Nombrar la fuente física real: objeto, material y acción. Nada de "cartoon", "comic", "magical", "sparkle".
#   2. Dar la perspectiva de grabación (close-mic, heard from inside a room...).
#   3. Lo que no suena en la realidad (la luz, una idea, el arcoíris) se resuelve con un objeto o un
#      instrumento acústico real: una bombilla que se enciende, una copa de cristal frotada, una marimba.
#   4. Una sola fuente por indicación; las capas se mezclan después.
import json, os

CREDITOS_POR_SEGUNDO = 3.333   # medido en el piloto: 1 s = 3,33 créditos por variación
VARIACIONES = 4

B = []
def S(nombre, cat, es, indicacion, dur, bucle=False, efectos=(), uso=None, piloto=None):
    B.append({"id": nombre, "categoria": cat, "es": es, "indicacion": indicacion, "duracion": dur,
              "bucle": bucle, "efectos_guia": list(efectos), "uso": uso, "piloto": piloto})

# ---------- Movimientos de la biblioteca 3D (config.json → movimientos) ----------
S("FOLEY_Plastilina_Cae", "FOLEY", "Plastilina que cae", "Soft lump of modeling clay dropped onto a wooden table, dull squishy thud, close-mic, dry studio", 1.0, uso="movimiento: cae", piloto="01")
