# ---------- Comprobaciones y salida ----------
ids = [b["id"] for b in B]
assert len(ids) == len(set(ids)), "ids repetidos"
cubre = [e for b in B for e in b["efectos_guia"]]
assert len(cubre) == len(set(cubre)), "un efecto de la guía está en dos sonidos"
faltan = [f"{n}.{i}" for n in range(1, 53) for i in range(4) if f"{n}.{i}" not in cubre]
assert not faltan, f"efectos de la guía sin sonido: {faltan}"
prohibidas = ("cartoon", "comic", "magical", "sparkl", "boing", "whimsical", "slide whistle")
for b in B:
    b["costo"] = round(b["duracion"] * CREDITOS_POR_SEGUNDO * VARIACIONES)
    b["cumple_realismo"] = not any(p in b["indicacion"].lower() for p in prohibidas) and "playful" not in b["indicacion"].lower()
nuevos = [b for b in B if not b["piloto"] or "nueva" in (b["piloto"] or "")]
salida = {
    "modelo": "eleven_text_to_sound_v3", "variaciones": VARIACIONES, "creditos_por_segundo": CREDITOS_POR_SEGUNDO,
    "reglas": ["Nombrar la fuente física real: objeto, material y acción.",
               "Dar la perspectiva de grabación.",
               "Lo que no suena en la realidad se resuelve con un objeto o un instrumento acústico real.",
               "Una sola fuente por indicación; las capas se mezclan después."],
    "resumen": {"sonidos": len(B), "efectos_de_la_guia_cubiertos": len(cubre), "ya_hechos_en_el_piloto": len(B) - len(nuevos),
                "por_generar": len(nuevos), "costo_por_generar": sum(b["costo"] for b in nuevos),
                "no_cumplen_realismo": [b["id"] for b in B if not b["cumple_realismo"]]},
    "sonidos": B}
destino = os.path.join(os.path.dirname(os.path.abspath(__file__)), "biblioteca.json")
json.dump(salida, open(destino, "w"), ensure_ascii=False, indent=1)
print(json.dumps(salida["resumen"], ensure_ascii=False, indent=1))
cats = {}
for b in B: cats[b["categoria"]] = cats.get(b["categoria"], 0) + 1
print(cats)
